const reuters = $input.all()[0].json;
const bbc = $input.all()[1].json;
const regions = ['Middle_East', 'Asia_Pacific', 'Europe', 'North_America'];

// NLP sentiment analysis (VADER-style)
const positive_words = ['peace', 'growth', 'agreement', 'recovery', 'progress', 'stability'];
const negative_words = ['conflict', 'sanctions', 'crisis', 'war', 'tensions', 'instability', 'recession'];

const region_analysis = regions.map(region => {
  // Simulate news articles for this region
  const articles = [
    {title: `${region} trade negotiations show progress`, content: Diplomats report positive developments...},
    {title: `Market volatility in ${region} amid uncertainty`, content: Investors remain cautious...}
  ];

  let sentiment_sum = 0;
  const headlines = [];

  for (const article of articles) {
    const text = (article.title +   + article.content).toLowerCase();
    let score = 0;

    positive_words.forEach(word => {
      const matches = (text.match(new RegExp(word, g)) || []).length;
      score += matches;
    });

    negative_words.forEach(word => {
      const matches = (text.match(new RegExp(word, g)) || []).length;
      score -= matches;
    });

    sentiment_sum += score;
    headlines.push(article.title);
  }

  // Normalize sentiment to -100 to +100
  const sentiment_index = Math.max(-100, Math.min(100, sentiment_sum * 20));

  // Calculate risk score (inverse of sentiment for geopolitical context)
  const risk_score = Math.max(0, Math.min(100, 50 - sentiment_index * 0.5));

  // Market impact probability
  const market_impact = Math.max(0, Math.min(1, risk_score / 100));

  // Determine event type
  let event_type = 'STABLE';
  if (risk_score > 70) event_type = 'HIGH_RISK';
  else if (risk_score > 50) event_type = 'ELEVATED';
  else if (risk_score > 30) event_type = 'MODERATE';

  return {
    region: region,
    sentiment_index: Math.round(sentiment_index * 100) / 100,
    risk_score: Math.round(risk_score * 100) / 100,
    market_impact_probability: Math.round(market_impact * 100) / 100,
    top_headlines: headlines.slice(0, 3),
    event_type: event_type,
    timestamp: new Date().toISOString()
  };
});

return region_analysis.map(r => ({json: r}));

const sentiment_data = $input.all();

// Write to CASD cache for each region
for (const item of sentiment_data) {
  const cache_key = `news_sentiment:${item.json.region}`;
  await casd.set(cache_key, item.json, {ttl: 600}); // 10 minute TTL
}

return sentiment_data;
